package nl.smartstreamlabs.sbwdroneconfig;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import net.minecraft.world.item.*;import java.util.*;
class DwfNativeStorageTest{
 @BeforeAll static void boot(){net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();}
 @Test void nativeNbtVariantsRemainSeparateAndRoundTrip()throws Exception{var a=new ItemStack(Items.COMPASS);a.getOrCreateTag().putString("Drone","first");a.getOrCreateTag().putLong("Battery",12345678);var b=a.copy();b.getOrCreateTag().putString("Drone","second");var pool=new DwfVariantPool();var store=new DwfStorage(64000000,65536,items->{},pool);assertEquals(30000000,store.insert(a,30000000,false));assertEquals(30000000,store.insert(b,30000000,false));assertEquals(2,store.counts.size());var key=pool.intern(a);assertEquals(key,pool.decode(key.encoded()));var out=store.extractStack(key,64000000,false);assertEquals(64,out.getCount());assertEquals("first",out.getTag().getString("Drone"));assertEquals(12345678,out.getTag().getLong("Battery"));assertEquals(29999936,store.counts.count(key));}
 @Test void nativeAutomationSimulationsDoNotInternOrChangeCounts(){var pool=new DwfVariantPool();var store=new DwfStorage(64000000,65536,items->{},pool);var stack=new ItemStack(Items.DIAMOND_SWORD);assertEquals(64000000,store.insert(stack,64000000,true));assertEquals(0,store.counts.total());assertNull(pool.find(stack));assertEquals(64000000,store.insert(stack,64000000,false));var handler=store.handler(()->true,()->true,()->true);long revision=store.counts.revision();assertEquals(1,handler.extractItem(0,1000000000,true).getCount());assertEquals(revision,store.counts.revision());assertEquals(64000000,store.counts.total());assertEquals(1,handler.extractItem(0,1000000000,false).getCount());assertEquals(63999999,store.counts.total());}
 @Test void restoredIndexIsBuiltFromFrozenMetadataAndPublishedOnOwnerThread()throws Exception{var source=new DwfItemKey(new ItemStack(Items.IRON_INGOT));var storage=new DwfStorage(64000000,65536,items->{});storage.beginLoad();storage.restoreBatch(List.of(new DwfIo.Record(0,source.encoded(),64000000)));storage.flush();var worker=java.util.concurrent.Executors.newSingleThreadExecutor();try{storage.prepareIndex(worker);long until=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(5);while(!storage.adoptIndex()&&System.nanoTime()<until)Thread.sleep(1);assertTrue(storage.adoptIndex());assertEquals(1,storage.index.size());assertEquals(64000000,storage.available(net.minecraft.world.item.crafting.Ingredient.of(Items.IRON_INGOT)));assertEquals(64,storage.extractStack(source,64,false).getCount());assertEquals(63999936,storage.available(net.minecraft.world.item.crafting.Ingredient.of(Items.IRON_INGOT)));}finally{worker.shutdownNow();}}
 @Test void repeatedPhysicalTransfersCoalesceUnderOneSharedTransportJob(){var work=new DwfWorkBudget();int[]notifications={0};var store=new DwfStorage(64000000,65536,items->{});store.useBudget(work);store.addListener(changes->{notifications[0]++;assertEquals(1000,changes.get(0).count());});for(int i=0;i<1000;i++)assertEquals(1,store.insert(new ItemStack(Items.IRON_INGOT),1,false));assertEquals(1000,store.counts.total());assertEquals(0,store.index.size());assertEquals(0,notifications[0]);assertEquals(1,work.size());work.tick(8,1000000000,Map.of(),false);assertEquals(1,notifications[0]);assertEquals(1,store.index.size());assertEquals(1000,store.available(net.minecraft.world.item.crafting.Ingredient.of(Items.IRON_INGOT)));assertEquals(0,work.size());}
 @Test void coalescedVariantReplacementAtLongCapacityDoesNotOverflowMaterialIndex(){var work=new DwfWorkBudget();var store=new DwfStorage(Long.MAX_VALUE,65536,items->{});store.useBudget(work);var a=new ItemStack(Items.IRON_INGOT);a.getOrCreateTag().putInt("variant",1);var b=a.copy();b.getOrCreateTag().putInt("variant",2);store.insert(a,Long.MAX_VALUE-1,false);store.insert(b,1,false);work.tick(8,1000000000,Map.of(),false);var keyA=store.counts.canonical(DwfItemKey.probe(a));var keyB=store.counts.canonical(DwfItemKey.probe(b));store.extractStack(keyB,1,false);store.counts.extract(keyA,Long.MAX_VALUE-1,false);store.flush();assertEquals(Long.MAX_VALUE,store.insert(b,Long.MAX_VALUE,false));work.tick(8,1000000000,Map.of(),false);assertEquals(Long.MAX_VALUE,store.counts.total());assertEquals(Long.MAX_VALUE,store.index.count(keyB));assertEquals(Long.MAX_VALUE,store.available(net.minecraft.world.item.crafting.Ingredient.of(Items.IRON_INGOT)));}
}
